import{_ as o,o as r,c as a,a2 as e}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Управление памятью Bot","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/memory.md","filePath":"ru/guides/memory.md","lastUpdated":1792323081000}'),l={name:"ru/guides/memory.md"};function i(n,t,s,d,h,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="управление-памятью-bot" tabindex="-1">Управление памятью Bot <a class="header-anchor" href="#управление-памятью-bot" aria-label="Permalink to &quot;Управление памятью Bot&quot;">​</a></h1><p>Структурированная система долговременной памяти Memoh позволяет Bot запоминать информацию между разговорами, делая взаимодействие контекстно уместным и персонализированным.</p><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><p>Прежде чем пользоваться вкладкой <strong>Memory</strong>, убедитесь, что у Bot уже настроен <strong>Memory Provider</strong> (провайдер памяти).</p><ol><li>Создайте провайдер одного из типов на странице <a href="./../integrations/providers/memory/builtin.html">провайдеров памяти</a> (встроенный, Mem0 или OpenViking).</li><li>Откройте вкладку <strong>General</strong> вашего Bot.</li><li>Выберите провайдер в поле <strong>Memory Provider</strong>.</li><li>Нажмите <strong>Save</strong>.</li></ol><p>Без провайдера памяти у Bot не будет активной конфигурации бэкенда памяти.</p><hr><h2 id="идея-извлечение-воспоминании" tabindex="-1">Идея: извлечение воспоминаний <a class="header-anchor" href="#идея-извлечение-воспоминании" aria-label="Permalink to &quot;Идея: извлечение воспоминаний&quot;">​</a></h2><p>Воспоминания сохраняются и извлекаются через назначенный провайдер памяти. В зависимости от типа провайдера извлечение может использовать встроенный граф памяти, векторы pgvector или внешний API. Когда пользователь отправляет сообщение, Memoh находит наиболее релевантные воспоминания и включает их в рабочий контекст Bot.</p><p>Эта страница — о <strong>долговременной памяти</strong>. Это не то же самое, что <strong>сжатие контекста сессии</strong>, которое уменьшает объём промпта одной сессии разговора. См. <a href="./compaction.html">Сжатие контекста</a>.</p><hr><h2 id="операции" tabindex="-1">Операции <a class="header-anchor" href="#операции" aria-label="Permalink to &quot;Операции&quot;">​</a></h2><p>Воспоминаниями Bot вы управляете на вкладке <strong>Memory</strong> страницы Bot.</p><h3 id="_1-создание-воспоминании" tabindex="-1">1. Создание воспоминаний <a class="header-anchor" href="#_1-создание-воспоминании" aria-label="Permalink to &quot;1. Создание воспоминаний&quot;">​</a></h3><ul><li><strong>New Memory</strong>: вручную введите содержимое воспоминания в текстовое поле.</li><li><strong>From Conversation</strong>: выберите конкретные сообщения из истории разговоров Bot, чтобы извлечь их в память.</li></ul><h3 id="_2-поиск-и-управление" tabindex="-1">2. Поиск и управление <a class="header-anchor" href="#_2-поиск-и-управление" aria-label="Permalink to &quot;2. Поиск и управление&quot;">​</a></h3><ul><li><strong>Search</strong>: фильтрация воспоминаний по ID или тексту.</li><li><strong>Edit</strong>: правка существующих записей прямо в списке.</li><li><strong>Delete</strong>: удаление воспоминаний, которые больше не нужны.</li></ul><hr><h2 id="сжатие-памяти" tabindex="-1">Сжатие памяти <a class="header-anchor" href="#сжатие-памяти" aria-label="Permalink to &quot;Сжатие памяти&quot;">​</a></h2><p>Со временем долговременные воспоминания накапливаются и начинают дублировать друг друга. Действие <strong>Compact</strong> на вкладке <strong>Memory</strong> переписывает сам хранимый набор воспоминаний.</p><p>Эта операция — обслуживание памяти на уровне провайдера. Она полезна, когда вы хотите:</p><ul><li>объединить пересекающиеся воспоминания;</li><li>убрать устаревшие или малоценные записи;</li><li>улучшить качество извлечения, снизив шум.</li></ul><p>Параметры:</p><ul><li><strong>Ratio</strong> — коэффициент сжатия, например <code>0.8</code>, <code>0.5</code> или <code>0.3</code>. Чем ниже значение, тем агрессивнее сжатие.</li><li><strong>Decay Days</strong> — опционально ограничивает сжатие только более старыми воспоминаниями.</li></ul><p>Это не то же самое, что <a href="./compaction.html">сжатие контекста</a>: то сжимает активный промпт одной сессии, а не переписывает хранимые воспоминания.</p><hr><h2 id="rebuild" tabindex="-1">Rebuild <a class="header-anchor" href="#rebuild" aria-label="Permalink to &quot;Rebuild&quot;">​</a></h2><p>Функция <strong>Rebuild</strong> переиндексирует все воспоминания с нуля. Это полезно, когда:</p><ul><li>вы сменили модель эмбеддингов у провайдера памяти;</li><li>векторный индекс пришёл в несогласованное состояние;</li><li>вы хотите заново обработать все воспоминания с обновлёнными настройками.</li></ul><p>Нажмите <strong>Rebuild</strong> на вкладке Memory, чтобы запустить процесс. За ходом перестроения можно следить в реальном времени.</p><hr><h2 id="статус" tabindex="-1">Статус <a class="header-anchor" href="#статус" aria-label="Permalink to &quot;Статус&quot;">​</a></h2><p>Вкладка Memory показывает текущий <strong>статус</strong> провайдера памяти для этого Bot:</p><ul><li><strong>Connected</strong> — бэкенд памяти доступен и работает.</li><li><strong>Error</strong> — есть проблема с конфигурацией провайдера памяти или с подключением.</li></ul><p>По индикатору статуса удобно быстро убедиться, что система памяти работает, прежде чем разбираться с другими проблемами.</p><hr><h2 id="статистика-использования" tabindex="-1">Статистика использования <a class="header-anchor" href="#статистика-использования" aria-label="Permalink to &quot;Статистика использования&quot;">​</a></h2><p>Вкладка Memory отображает сведения об использовании хранилища:</p><ul><li><strong>Total Memories</strong> — число записей памяти, сохранённых для этого Bot.</li><li><strong>Index Status</strong> — актуален ли векторный индекс.</li></ul><hr><h2 id="память-и-контекст-сессии" tabindex="-1">Память и контекст сессии <a class="header-anchor" href="#память-и-контекст-сессии" aria-label="Permalink to &quot;Память и контекст сессии&quot;">​</a></h2><p>В Memoh есть два разных понятия «сжатия»:</p><table tabindex="0"><thead><tr><th>Понятие</th><th>Область действия</th><th>Где запускается</th><th>Что меняет</th></tr></thead><tbody><tr><td><strong>Сжатие памяти</strong></td><td>Провайдер долговременной памяти</td><td>Вкладка Memory</td><td>Переписывает хранимые записи памяти</td></tr><tr><td><strong>Сжатие контекста</strong></td><td>Одна сессия разговора</td><td>Панель статуса сессии или <code>/compact</code></td><td>Сводит старый контекст сессии в резюме для будущих вызовов модели</td></tr></tbody></table><p>Если нужно снизить шум при извлечении по множеству разговоров — используйте <strong>сжатие памяти</strong>.</p><p>Если нужно укоротить историю текущего активного разговора — используйте <strong>сжатие контекста</strong>.</p><hr><h2 id="взаимодеиствие-с-bot" tabindex="-1">Взаимодействие с Bot <a class="header-anchor" href="#взаимодеиствие-с-bot" aria-label="Permalink to &quot;Взаимодействие с Bot&quot;">​</a></h2><ul><li>Во время чата Bot сам ищет и извлекает воспоминания.</li><li>Назначенный <strong>Memory Provider</strong> определяет бэкенд памяти, который использует Bot.</li><li>Настройки конкретного провайдера (например, модель эмбеддингов или API-ключи) задаются на самом провайдере — см. <a href="./../integrations/providers/memory/builtin.html">Провайдеры памяти</a>.</li><li>Воспоминания дают те долговременные знания, которые делают каждого Bot уникальным для его владельца.</li></ul>',48)])])}const c=o(l,[["render",i]]);export{m as __pageData,c as default};
